correction.text:
{
  "corrected": "I am Karthik and I have two years of sales experience.",
  "mistakes": [
    {
      "wrong": "Myself Karthik",
      "right": "I am Karthik",
      "type": "grammar",
      "explanation_tamil": "நான் என்பதற்கு 'மெய்ம்' பயன்படுத்தக்கூடாது."
    },
    {
      "wrong": "having",
      "right": "have",
      "type": "grammar",
      "explanation_tamil": "இந்தக் காலத்தில் 'have' என்பதே சரியானது."
    },
    {
      "wrong": "in sales",
      "right": "of sales",
      "type": "style",
      "explanation_tamil": "பொருளாதாரத் துறையில் பணிபுரிவதற்கு 'of' என்பது சிறந்தது."
    }
  ]
}

{
  "corrected": "I have been working at this company since 2019.",
  "mistakes": [
    {
      "wrong": "working",
      "right": "have been working",
      "type": "grammar",
      "explanation_tamil": "இந்தச் சொல்லில் 'have been working' என்று மாற்ற வேண்டும்."
    },
    {
      "wrong": "in",
      "right": "at",
      "type": "style",
      "explanation_tamil": "நிறுவனத்தில் பணிபுரியும்போது 'at' என்பதைப் பயன்படுத்த வேண்டும்."
    }
  ]
}

{
  "corrected": "Please revert to me today.",
  "mistakes": [
    {
      "wrong": "revert back",
      "right": "revert",
      "type": "style",
      "explanation_tamil": "பிரிவுக்குத் திரும்புவதற்கு 'revert back' என்று சொல்லக்கூடாது; 'revert' போதுமானது."
    }
  ]
}

{
  "corrected": "We discussed the budget and he said it was fine.",
  "mistakes": [
    {
      "wrong": "discussed about",
      "right": "discussed",
      "type": "grammar",
      "explanation_tamil": "பகுப்பாய்வு செய்வதில் 'about' பயன்படுத்தக்கூடாது."
    },
    {
      "wrong": "told that",
      "right": "said",
      "type": "grammar",
      "explanation_tamil": "பெயர்ச்சொல்லைச் சொல்லும்போது 'said' என்று பயன்படுத்த வேண்டும்."
    },
    {
      "wrong": "it is",
      "right": "it was",
      "type": "grammar",
      "explanation_tamil": "முன்னுரைக்கும் பின்னணிக்கு ஏற்றபடி 'was' பயன்படுத்த வேண்டும்."
    }
  ]
}

{
  "corrected": "Please take the necessary action and send the files.",
  "mistakes": [
    {
      "wrong": "Kindly do the needful",
      "right": "Please take the necessary action",
      "type": "style",
      "explanation_tamil": "இந்த வார்த்தைகள் தொழில்முறைத் தமிழில் பயன்படுத்தப்படாது."
    }
  ]
}

{
  "corrected": "What is your full name?",
  "mistakes": [
    {
      "wrong": "good name",
      "right": "full name",
      "type": "style",
      "explanation_tamil": "பொருளாதாரத் துறையில் 'full name' என்பதே சரியானது."
    }
  ]
}

{
  "corrected": "I have been working here for three years and I enjoy my role.",
  "mistakes": []
}

{
  "corrected": "Could you please send me the updated report by Friday?",
  "mistakes": []
}
